scan_regions = input('scan_regions')
exempt       = (input('exempt_assets') || {})['CKV_AWS_74'] || []

control 'CKV_AWS_74' do
  title 'Ensure DocumentDB is encrypted at rest (default is unencrypted)'

  desc <<~DESC
    Checkov asserts this against Terraform. This profile asserts it against
    the aws_docdb_cluster resources that actually exist, enumerated through
    the declarative API spec.
  DESC

  desc 'rationale', <<~RATIONALE
    DocumentDB storage is unencrypted by default and encryption cannot be
    turned on after creation -- the cluster has to be restored into a new
    encrypted one. Finding this on a deployed cluster is finding a
    migration, which is why it matters that it is found early.
  RATIONALE

  desc 'check', <<~CHECK
    Checkov looks for: aws_docdb_cluster: storage_encrypted is True
  CHECK

  desc 'fix', <<~'FIX'
    Terraform — aws_docdb_cluster:

      resource "aws_docdb_cluster" "docs" {
        cluster_identifier      = "docs"
        engine                  = "docdb"
        master_username         = var.master_username
        master_password         = var.master_password
        storage_encrypted       = true
        kms_key_id              = aws_kms_key.docdb.arn
        backup_retention_period = 7
        skip_final_snapshot     = false
        final_snapshot_identifier = "docs-final"
      }

    Out of band — aws_docdb_cluster:

      There is no in-place fix. DocumentDB storage encryption is set at
      creation only. Snapshot, restore encrypted, cut over, delete the original:
      aws docdb create-db-cluster-snapshot --db-cluster-identifier docs --db-cluster-snapshot-identifier docs-migrate
      aws docdb restore-db-cluster-from-snapshot --db-cluster-identifier docs-enc --snapshot-identifier docs-migrate --engine docdb --storage-encrypted --kms-key-id <key-arn>
  FIX

  tag checkov_id:            'CKV_AWS_74'
  tag checkov_category:      'ENCRYPTION'
  tag checkov_version:       '3.3.16'
  tag checkov_kind:          'value'
  tag tf_resources:          %w[aws_docdb_cluster]
  tag tf_docs:               'https://registry.terraform.io/providers/hashicorp/aws/latest/docs/resources/docdb_cluster#storage-encrypted'
  tag nist:                  ['SC-28', 'SC-28 (1)']
  tag nist_r4:               ['SC-28', 'SC-28 (1)']
  tag cci:                   ['CCI-001199', 'CCI-002475']
  tag ksi:                   ['KSI-SVC-CER']
  tag severity:              'high'
  tag severity_source:       'assessed'
  tag nist_source:           'agent-drafted'
  tag implementation_status: 'implemented'

  assets = aws_api_assets(type: 'aws_docdb_cluster', regions: scan_regions)

  # A field the API did not return is nil, and nil is not a failing value:
  # the asset does not express this setting, so it is out of scope for this
  # check rather than in breach of it.
  in_scope = assets.assets(exempt: exempt)
                   .reject { |a| a[:storage_encrypted].nil? }

  applicable = !in_scope.empty?
  impact 0.7
  impact 0.0 unless applicable
  only_if('no aws_docdb_cluster in scope expressing this setting') { applicable }

  in_scope.each do |asset|
    describe "aws_docdb_cluster #{asset[:id]} (#{asset[:account_id]}/#{asset[:region]})" do
      subject { asset[:storage_encrypted] }
      it { should eq true }
    end
  end
end
